<?php
namespace App\Http\Controllers;
use Illuminate\Routing\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash,Mail,Storage};
use Illuminate\Support\Str;
use App\Services\{Support,Dispatch,Workflow,Commerce};
class OperationsController extends Controller {
 private function company():int {abort_unless(auth()->user()->role==='sorting_center',403);return auth()->id();}
 private function center():int {$id=DB::table('sorting_centers')->where('user_id',$this->company())->value('id');abort_unless($id,403);return $id;}
 private function done(Request $r,string $message,$data=null){return $r->expectsJson()?response()->json(['message'=>$message,'data'=>$data]):back()->with('success',$message);}
 public function panel(Request $r,string $module='overview'){
  $module=$r->route('module')??$module;$u=auth()->user();if($u->role==='logistics_admin'&&in_array($module,['territories','legacy']))return app(LogisticsWorkspaceController::class)->$module($r);if($u->role==='sorting_center'&&$module==='overview')return app(LogisticsWorkspaceController::class)->overview($r);$forms=[];$records=collect();$title=ucfirst($module);$form=function($label,$action,$fields)use(&$forms){$forms[]=compact('label','action','fields');};
  if($u->role==='logistics_admin'){if($module==='territories'){return view('tools',['links'=>app(CommonController::class)->links(),'title'=>'Sorting center municipalities','records'=>DB::table('sorting_centers')->get(['id','name','city','province','municipality_key'])->map(function($c){$c->territory_status=$c->municipality_key?'Assigned':'Needs municipality assignment';return $c;}),'forms'=>[['label'=>'Set registered municipality','action'=>'/admin/territory','fields'=>['center_id:number','region','province','city','barangay','street','postal_code','reason:textarea']]]]);}if($module!=='legacy')abort(404);$records=DB::table('users')->where('role','rider')->whereNull('company_id')->get(['id','name','email','approval_status']);$form('Attach legacy rider to a logistics company','/ops/legacy',['rider_id:number','company_id:number','courier_type:select:rider,driver','vehicle:select:motorcycle,tricycle,4-wheel truck,6-wheel truck,8-wheel truck,10-wheel truck','reason:textarea']);}
  elseif($u->role==='rider'){
   if($module==='availability'){$records=collect([['online'=>$u->online,'active_jobs'=>DB::table('assignments')->where('rider_id',$u->id)->where('status','accepted')->count()]]);$form('Update location','/ops/location',['latitude:number','longitude:number']);$form('Decline offer','/ops/decline',['id:number']);}
   elseif($module==='cod'){$records=DB::table('remittances')->where('rider_id',$u->id)->get();$balance=DB::table('cod_collections')->where('rider_id',$u->id)->whereNull('remittance_id')->sum('amount');$title='COD to remit: PHP '.number_format($balance,2);$form('Submit COD remittance','/ops/remit',['amount:number','reference']);$form('Top up short remittance','/ops/remit/topup',['id:number','amount:number','reference']);}
   elseif($module==='vehicle'){$records=collect([['name'=>$u->name,'vehicle'=>$u->vehicle,'license_number'=>$u->license_number,'license_expires_at'=>$u->license_expires_at,'plate_number'=>$u->plate_number]]);$form('Vehicle and documents','/ops/vehicle',['vehicle','license_number','license_expires_at:date','plate_number','id_document:file?','permit_document:file?']);}
   else abort(404);
  }elseif($u->role==='sorting_center'){
   $center=$this->center();
   if($module==='riders'){$records=DB::table('users')->where('company_id',$u->id)->where('role','rider')->get(['id','name','email','phone','approval_status','active','online','vehicle','plate_number','courier_type']);$form('Invite rider or driver','/ops/rider',['first_name','last_name','email:email','phone','date_of_birth:date','courier_type:select:rider,driver','vehicle:select:motorcycle,tricycle,4-wheel truck,6-wheel truck,8-wheel truck,10-wheel truck','license_number','license_expires_at:date','plate_number','id_document:file','permit_document:file']);$form('Suspend/reactivate rider','/ops/rider/status',['id:number','active:checkbox','reason:textarea']);$form('Resend activation','/ops/rider/resend',['id:number']);}
   elseif($module==='transfers')return app(TransferController::class)->index();
   elseif($module==='rates'){$records=DB::table('shipping_rates')->where('center_id',$center)->get();$form('Save shipping rate','/ops/rate',['id?','origin_province?','city','province','base_fee:number','extra_kg_fee:number','active:checkbox','reason:textarea']);}
   elseif($module==='dispatch'){$records=DB::table('parcels')->where('center_id',$center)->whereIn('status',['SORTED','DELIVERY_FAILED','ASSIGNED_TO_RIDER'])->get();$form('Dispatch/reassign delivery (empty rider chooses lowest workload)','/ops/dispatch',['parcel_id:number','rider_id:number?','reason:textarea']);}
   elseif($module==='cod'){$records=DB::table('remittances')->where('company_id',$u->id)->get();$form('Confirm remittance','/ops/remittance/confirm',['id:number','reason:textarea']);}
   elseif($module==='tracking'){$q=DB::table('parcels as p')->join('orders as o','o.id','=','p.order_id')->join('users as b','b.id','=','o.buyer_id')->where('p.center_id',$center);if($r->filled('q'))$q->where(fn($x)=>$x->where('p.tracking_code',$r->q)->orWhere('o.id',$r->q)->orWhere('b.name','like','%'.$r->q.'%'));$records=$q->select('p.*','b.name as buyer')->get();$form('Mark parcel lost/damaged','/ops/exception',['parcel_id:number','status:select:LOST,DAMAGED','reason:textarea','proof:file?']);$form('Override operational status','/ops/override',['parcel_id:number','status:select:AT_SORTING_CENTER,SORTED,DELIVERY_FAILED,RETURN_TO_SENDER','reason:textarea']);}
   elseif($module==='returns'){$records=DB::table('parcels')->where('center_id',$center)->whereIn('status',['RETURN_TO_SENDER','RETURNED'])->get();$form('Confirm returned to seller','/ops/returned',['parcel_id:number']);}
   elseif($module==='overview'){$form('Update dispatch origin','/ops/location',['latitude:number','longitude:number']);$q=DB::table('parcels')->where('center_id',$center);if($r->filled('from'))$q->whereDate('created_at','>=',$r->date('from'));if($r->filled('to'))$q->whereDate('created_at','<=',$r->date('to'));$records=$q->select('status',DB::raw('COUNT(*) as count'))->groupBy('status')->get();}
   else abort(404);
  }else abort(403);
  return view('tools',['links'=>app(CommonController::class)->links(),'title'=>$title,'forms'=>$forms,'records'=>$records]);
 }
 public function rider(Request $r){$company=$this->company();$r->merge(['phone'=>\App\Services\Registration::normalizePhone((string)$r->phone),'email'=>mb_strtolower(trim((string)$r->email)),'plate_number'=>strtoupper(trim((string)$r->plate_number))]);
  $v=$r->validate(['first_name'=>['required','string','min:2','max:50',"regex:/^[\p{L}\p{M} .'-]+$/u"],'last_name'=>['required','string','min:2','max:50',"regex:/^[\p{L}\p{M} .'-]+$/u"],'email'=>'required|email|unique:users,email','phone'=>['required','regex:/^09[0-9]{9}$/','unique:users,phone_normalized'],'date_of_birth'=>'required|date|before_or_equal:'.now()->subYears(18)->toDateString(),'courier_type'=>'required|in:rider,driver','vehicle'=>'required|string|max:120','license_number'=>['required','regex:/^[A-Z][0-9]{2}-[0-9]{2}-[0-9]{6}$/','unique:users,license_number'],'license_expires_at'=>'required|date|after_or_equal:today','plate_number'=>'required|string|max:20|unique:users,plate_number','id_document'=>'required|file|mimes:jpg,jpeg,png,pdf|extensions:jpg,jpeg,png,pdf|max:5120','permit_document'=>'required|file|mimes:jpg,jpeg,png,pdf|extensions:jpg,jpeg,png,pdf|max:5120']);
  \App\Services\Fleet::validate($v['courier_type'],$v['vehicle']);$id=Support::once($r,'rider-invite',function()use($r,$v,$company){$data=$v;unset($data['id_document'],$data['permit_document']);$data+=['name'=>$v['first_name'].' '.$v['last_name'],'phone_normalized'=>$v['phone'],'role'=>'rider','company_id'=>$company,'approval_status'=>'pending_activation','verification_required'=>1,'active'=>1,'password'=>Hash::make(Str::random(48)),'created_at'=>now(),'updated_at'=>now()];$id=DB::table('users')->insertGetId($data);\App\Services\Fleet::address($id,$company);foreach(['id_document','permit_document'] as $field)DB::table('registration_documents')->insert(['user_id'=>$id,'kind'=>$field,'path'=>$r->file($field)->store('documents','local'),'created_at'=>now(),'updated_at'=>now()]);$this->invite($id);Support::audit('rider-invited','user',$id,null,['company_id'=>$company]);return $id;});return $this->done($r,'Courier invited. They must activate by email.',$id);
 }
 private function invite(int $id):void {$u=DB::table('users')->find($id);$token=Str::random(64);DB::table('users')->where('id',$id)->update(['activation_hash'=>hash('sha256',$token),'activation_expires_at'=>now()->addHours(24)]);$url=url('/activate/'.$id.'/'.$token);Mail::raw('Set your rider password within 24 hours: '.$url,fn($m)=>$m->to($u->email)->subject('Activate your rider account'));}
 public function resend(Request $r){$id=$r->validate(['id'=>'required|integer'])['id'];$u=DB::table('users')->where('id',$id)->where('company_id',$this->company())->where('approval_status','pending_activation')->first();abort_unless($u,404);$this->invite($id);return $this->done($r,'Activation email resent; old link invalidated.');}
 public function activateForm(int $id,string $token){$u=DB::table('users')->find($id);abort_unless($u&&$u->approval_status==='pending_activation'&&$u->activation_hash&&hash_equals($u->activation_hash,hash('sha256',$token))&&now()->lt($u->activation_expires_at),403);return view('guest-tools',['title'=>'Activate rider account','forms'=>[['label'=>'Set password','action'=>url('/activate/'.$id.'/'.$token),'fields'=>['password:password','password_confirmation:password']]]]);}
 public function activate(Request $r,int $id,string $token){$v=$r->validate(['password'=>['required','confirmed',\Illuminate\Validation\Rules\Password::min(8)->mixedCase()->numbers()->symbols()]]);DB::transaction(function()use($id,$token,$v){$u=DB::table('users')->where('id',$id)->lockForUpdate()->first();abort_unless($u&&$u->approval_status==='pending_activation'&&$u->activation_hash&&hash_equals($u->activation_hash,hash('sha256',$token))&&now()->lt($u->activation_expires_at),403);DB::table('users')->where('id',$id)->update(['password'=>Hash::make($v['password']),'approval_status'=>'approved','email_verified_at'=>now(),'activation_hash'=>null,'activation_expires_at'=>null,'updated_at'=>now()]);Support::email($id,'Courier account activated','Your email is verified and your logistics account is now active. You can log in.');});return redirect('/login')->with('success','Rider account activated. Log in.');}
 public function riderStatus(Request $r){$v=$r->validate(['id'=>'required|integer','active'=>'nullable|boolean','reason'=>'required|string|min:10|max:300']);$company=$this->company();DB::transaction(function()use($v,$r,$company){$u=DB::table('users')->where('id',$v['id'])->where('company_id',$company)->where('role','rider')->lockForUpdate()->first();abort_unless($u,403);if($u->account_status!=='active')Support::fail('active','An administrator must restore this account first.');DB::table('users')->where('id',$u->id)->update(['active'=>$r->boolean('active'),'online'=>0,'updated_at'=>now()]);if(!$r->boolean('active'))DB::table('assignments')->where('rider_id',$u->id)->whereIn('status',['offered','accepted'])->whereIn('parcel_id',DB::table('parcels')->whereIn('status',['PREPARING','READY_FOR_PICKUP','SORTED','ASSIGNED_TO_RIDER','DELIVERY_FAILED'])->select('id'))->update(['status'=>'unassigned','updated_at'=>now()]);Support::audit('rider-status','user',$u->id,$u,['active'=>$r->boolean('active')],$v['reason']);});return $this->done($r,'Rider status saved.');}
 public function availability(Request $r){$r->validate(['online'=>'nullable|boolean']);$u=auth()->user();abort_unless($u->role==='rider',403);if(!$r->boolean('online')&&DB::table('assignments')->where('rider_id',$u->id)->where('status','accepted')->exists())Support::fail('online','Finish active jobs before going Offline.');DB::table('users')->where('id',$u->id)->update(['online'=>$r->boolean('online'),'last_seen_at'=>now(),'updated_at'=>now()]);return $this->done($r,$r->boolean('online')?'You are Active / Online and ready for assignments.':'You are Not active / Offline.');}
 public function decline(Request $r){$id=$r->validate(['id'=>'required|integer'])['id'];$u=auth()->user();abort_unless($u->role==='rider',403);DB::transaction(function()use($id,$u){$a=DB::table('assignments')->where('id',$id)->where('rider_id',$u->id)->lockForUpdate()->first();abort_unless($a,403);if($a->status!=='offered')Support::fail('assignment','Offer is no longer available.');DB::table('assignments')->where('id',$id)->update(['status'=>'declined','updated_at'=>now()]);});return $this->done($r,'Offer declined.');}
 public function dispatch(Request $r){$v=$r->validate(['parcel_id'=>'required|integer','rider_id'=>'nullable|integer','reason'=>'required|string|min:10|max:300']);$company=$this->company();$p=DB::table('parcels')->where('id',$v['parcel_id'])->where('center_id',$this->center())->first();abort_unless($p,403);Dispatch::offer($p->id,$company,$v['rider_id']??null);Support::audit('dispatch','parcel',$p->id,$p,['rider_id'=>$v['rider_id']??null],$v['reason']);return $this->done($r,'Offer sent.');}
 public function rate(Request $r){$v=$r->validate(['id'=>'nullable|integer','origin_province'=>'nullable|string|max:120','city'=>'required|string|max:120','province'=>'required|string|max:120','base_fee'=>'required|numeric|decimal:0,2|min:0','extra_kg_fee'=>'required|numeric|decimal:0,2|min:0','active'=>'nullable|boolean','reason'=>'required|string|min:10|max:300']);$center=$this->center();$territory=DB::table('sorting_centers')->find($center);if(!\App\Services\Municipalities::matches($territory,(object)$v))Support::fail('city','Add shipping rates only for your registered municipality.');$id=$v['id']??null;$reason=$v['reason'];unset($v['id'],$v['reason']);$v['active']=$r->boolean('active');$v['origin_province']=$v['origin_province']??'';DB::transaction(function()use($id,$v,$reason,$center){$old=$id?DB::table('shipping_rates')->where('id',$id)->where('center_id',$center)->first():null;if($id)abort_unless($old,403);if(DB::table('shipping_rates')->where('center_id',$center)->where('origin_province',$v['origin_province'])->where('city',$v['city'])->where('province',$v['province'])->when($id,fn($q)=>$q->where('id','!=',$id))->exists())Support::fail('city','A rate for this destination already exists.');if($id)DB::table('shipping_rates')->where('id',$id)->update($v+['updated_at'=>now()]);else $id=DB::table('shipping_rates')->insertGetId($v+['center_id'=>$center,'created_at'=>now(),'updated_at'=>now()]);Support::audit('shipping-rate','shipping_rate',$id,$old,$v,$reason);});return $this->done($r,'Rate saved for new checkouts.');}
 public function remit(Request $r){abort_unless(auth()->user()->role==='rider'&&auth()->user()->company_id,403);$v=$r->validate(['amount'=>'required|numeric|decimal:0,2|gt:0','reference'=>'required|string|max:190']);$id=Support::once($r,'cod-remit',function()use($v){$u=auth()->user();if(DB::table('remittances')->where('rider_id',$u->id)->whereIn('status',['pending','short'])->exists())Support::fail('remittance','Resolve the existing remittance first.');$rows=DB::table('cod_collections')->where('rider_id',$u->id)->whereNull('remittance_id')->lockForUpdate()->get();$expected=Support::money($rows->sum('amount'));if($expected<=0||$v['amount']>$expected)Support::fail('amount','No matching COD balance, or amount exceeds collected COD.');$id=DB::table('remittances')->insertGetId($v+['rider_id'=>$u->id,'company_id'=>$u->company_id,'expected'=>$expected,'status'=>$v['amount']<$expected?'short':'pending','created_at'=>now(),'updated_at'=>now()]);DB::table('cod_collections')->whereIn('id',$rows->pluck('id'))->update(['remittance_id'=>$id]);Support::notify([$u->company_id],"COD remittance #{$id} submitted.");return $id;});return $this->done($r,'Remittance submitted; differences are flagged.',$id);}
 public function confirm(Request $r){$v=$r->validate(['id'=>'required|integer','reason'=>'required|string|min:10|max:300']);$company=$this->company();DB::transaction(function()use($v,$company){$x=DB::table('remittances')->where('id',$v['id'])->where('company_id',$company)->lockForUpdate()->first();abort_unless($x&&$x->rider_id!=$company,403);if($x->status==='confirmed')return;if(Support::money($x->expected)!==Support::money($x->amount))Support::fail('amount','Short remittance must be resolved before confirmation.');DB::table('remittances')->where('id',$x->id)->update(['status'=>'confirmed','confirmed_by'=>$company,'updated_at'=>now()]);Support::audit('remittance-confirmed','remittance',$x->id,$x,['status'=>'confirmed'],$v['reason']);});return $this->done($r,'Remittance confirmed.');}
 public function vehicle(Request $r){abort_unless(auth()->user()->role==='rider',403);$v=$r->validate(['vehicle'=>'required|string|max:120','license_number'=>['required','regex:/^[A-Z][0-9]{2}-[0-9]{2}-[0-9]{6}$/','unique:users,license_number,'.auth()->id()],'license_expires_at'=>'required|date|after_or_equal:today','plate_number'=>'required|string|max:20|unique:users,plate_number,'.auth()->id(),'id_document'=>'nullable|file|mimes:jpg,jpeg,png,pdf|extensions:jpg,jpeg,png,pdf|max:5120','permit_document'=>'nullable|file|mimes:jpg,jpeg,png,pdf|extensions:jpg,jpeg,png,pdf|max:5120']);\App\Services\Fleet::validate(auth()->user()->courier_type,$v['vehicle']);unset($v['id_document'],$v['permit_document']);DB::table('users')->where('id',auth()->id())->update($v+['updated_at'=>now()]);foreach(['id_document','permit_document'] as $f)if($r->hasFile($f))DB::table('registration_documents')->insert(['user_id'=>auth()->id(),'kind'=>$f,'path'=>$r->file($f)->store('documents','local'),'created_at'=>now(),'updated_at'=>now()]);return $this->done($r,'Vehicle saved.');}
 public function exception(Request $r){$v=$r->validate(['parcel_id'=>'required|integer','status'=>'required|in:LOST,DAMAGED','reason'=>'required|string|min:10|max:300','proof'=>'required_if:status,DAMAGED|nullable|file|mimes:jpg,jpeg,png|extensions:jpg,jpeg,png|max:5120']);$this->changeStatus($v['parcel_id'],$v['status'],$v['reason'],$r->hasFile('proof')?$r->file('proof')->store('exceptions','local'):null);return $this->done($r,'Exception recorded.');}
 public function override(Request $r){$v=$r->validate(['parcel_id'=>'required|integer','status'=>'required|in:AT_SORTING_CENTER,SORTED,DELIVERY_FAILED,RETURN_TO_SENDER','reason'=>'required|string|min:10|max:300']);$this->changeStatus($v['parcel_id'],$v['status'],$v['reason']);return $this->done($r,'Override recorded with audit history.');}
 private function changeStatus(int $id,string $to,string $reason,?string $photo=null):void{$center=$this->center();DB::transaction(function()use($id,$to,$reason,$center,$photo){$p=DB::table('parcels')->where('id',$id)->where('center_id',$center)->lockForUpdate()->first();abort_unless($p,403);if(in_array($p->status,['COMPLETED','CANCELLED','REFUNDED','RETURN_RECEIVED','DELIVERED']))Support::fail('status','A financial terminal state cannot be overridden.');DB::table('parcels')->where('id',$id)->update(['status'=>$to,'updated_at'=>now()]);DB::table('orders')->where('id',$p->order_id)->update(['status'=>$to,'updated_at'=>now()]);DB::table('status_history')->insert(['parcel_id'=>$id,'from_status'=>$p->status,'to_status'=>$to,'actor_id'=>auth()->id(),'reason'=>$reason,'created_at'=>now(),'updated_at'=>now()]);Support::audit('status-override','parcel',$id,$p,['status'=>$to,'evidence'=>$photo],$reason);$o=DB::table('orders')->find($p->order_id);Support::notify([$o->buyer_id,$o->seller_id],"Parcel {$p->tracking_code}: {$to} ({$reason})");});}
 public function returned(Request $r){$id=$r->validate(['parcel_id'=>'required|integer'])['parcel_id'];Workflow::move($id,'RETURNED',auth()->id(),null,null,$this->center());return $this->done($r,'Returned to seller. Stock awaits seller receipt confirmation.');}

 public function location(Request $r){$v=$r->validate(['latitude'=>'required|numeric|between:-90,90','longitude'=>'required|numeric|between:-180,180']);DB::table('users')->where('id',auth()->id())->update($v+['last_seen_at'=>now()]);return $this->done($r,'Location saved.');}
 public function legacy(Request $r){abort_unless(auth()->user()->role==='logistics_admin',403);$v=$r->validate(['rider_id'=>'required|integer','company_id'=>'required|integer','courier_type'=>'required|in:rider,driver','vehicle'=>'required|string|max:120','reason'=>'required|string|min:10|max:300']);abort_unless(DB::table('users')->where('id',$v['company_id'])->where('role','sorting_center')->where('approval_status','approved')->where('active',1)->where('account_status','active')->exists(),422);\App\Services\Fleet::validate($v['courier_type'],$v['vehicle']);DB::transaction(function()use($v){$u=DB::table('users')->where('id',$v['rider_id'])->where('role','rider')->whereNull('company_id')->lockForUpdate()->first();abort_unless($u,422);DB::table('users')->where('id',$u->id)->update(['company_id'=>$v['company_id'],'courier_type'=>$v['courier_type'],'vehicle'=>$v['vehicle'],'online'=>0,'updated_at'=>now()]);\App\Services\Fleet::address($u->id,$v['company_id']);if($u->approval_status!=='approved'){DB::table('users')->where('id',$u->id)->update(['approval_status'=>'pending_activation','verification_required'=>1]);$this->invite($u->id);}Support::audit('legacy-company-link','user',$u->id,$u,['company_id'=>$v['company_id']],$v['reason']);});return $this->done($r,'Legacy rider linked. Existing activation/approval state was preserved.');}

 public function topup(Request $r){abort_unless(auth()->user()->role==='rider',403);$v=$r->validate(['id'=>'required|integer','amount'=>'required|numeric|decimal:0,2|gt:0','reference'=>'required|string|max:190']);Support::once($r,'remittance-topup',function()use($v){$x=DB::table('remittances')->where('id',$v['id'])->where('rider_id',auth()->id())->lockForUpdate()->first();abort_unless($x&&$x->status==='short',422);$amount=Support::money($x->amount+$v['amount']);if($amount>$x->expected)Support::fail('amount','Top-up exceeds the shortage.');DB::table('remittances')->where('id',$x->id)->update(['amount'=>$amount,'status'=>$amount==$x->expected?'pending':'short','reference'=>$x->reference.'; '.$v['reference'],'updated_at'=>now()]);Support::audit('remittance-topup','remittance',$x->id,$x,['amount'=>$amount],$v['reference']);return $x->id;});return $this->done($r,'Top-up saved; logistics still needs to confirm.');}
}
